import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    t = int(data[0])
    results = []
    for i in range(1, t + 1):
        n_str = data[i]
        if n_str == n_str[::-1]:
            results.append("wins")
        else:
            results.append("loses")
    print('\n'.join(results))

if __name__ == "__main__":
    main()
